            data = readtable(filename);
            exp_data.alpha = data.alpha;
            exp_data.Cl = data.Cl;
            if ismember('Cp_upper', data.Properties.VariableNames)
                exp_data.Cp_upper = data.Cp_upper;
                exp_data.Cp_lower = data.Cp_lower;
                exp_data.x_Cp = data.x;
            end
        else
            error('Unsupported file format');
        end
        fprintf('✓ Loaded experimental data from %s\n', filename);
    catch ME
        error('Error loading experimental data: %s', ME.message);
    end
end

